`,"playbooks/launch-videos/kit/formats/irl/edit/timeline.js":`// The edit: filmed clips in order, headlines timed to the words, glass on the open side, and the end card.
// Clip times are seconds in the clip file (the transcript's clock); the end card's are from its own start.
// Clips live in media/clips/; measure their length with ffmpeg -i.
import { build } from "../core/timeline.js";
import { BRAND } from "./brand.js";

export const { WIDTH, HEIGHT, FPS, FRAMES, TOTAL, LAYOUT, SHOTS, SHOT, HEADLINES, NARRATION, MUSIC, CUTS, place, kept, shotAt } = build({
  canvas: BRAND.canvas,
  // Match the camera: 24000 / 1001 for 23.976 footage, 30 for 30p.
  fps: 24000 / 1001,
  shots: [
    // overlays: the side with open space (the speaker stands on the other). corner: the free top corner for the mark.
    // A launch film plays its clips whole. To start on the first word or tighten a long pause, give the clip
    // keep: [[from, to], ...] from node scripts/pauses.mjs instead of from/to.
    { id: "intro", kind: "clip", file: "clip1.mov", from: 0, to: 12, overlays: "right", corner: "left" },
    { id: "how", kind: "clip", file: "clip2.mov", from: 0, to: 14, overlays: "left", corner: "right" },
    // The end card plays over a quiet clip (its sound kept low), or over the brand background without \`file\`.
    { id: "end", kind: "end", file: "end.mov", from: 0.5, to: 6.5 },
  ],
  // [shot, start, end, side, "line one|line two"]. Each spans a whole phrase and holds at least 2.2s.
  headlines: [
    ["intro", 0.2, 4.6, "left", "Acme|Every invoice, one inbox"],
    ["how", 0.3, 4.8, "right", "Ready in|two minutes"],
  ],
  // Off by default. With the user's go-ahead: a licensed or generated track at media/music.wav, ducked under speech.
  music: null,
});
