// narration timed to the words, and the end card. Times are seconds from the start of each shot.
import { build } from "../core/timeline.js";
import { BRAND } from "./brand.js";

export const { WIDTH, HEIGHT, FPS, FRAMES, TOTAL, LAYOUT, SHOTS, SHOT, HEADLINES, NARRATION, MUSIC, CUTS, place, kept, shotAt } = build({
  canvas: BRAND.canvas,
  fps: 30,
  shots: [
    {
      id: "inbox", kind: "ui", len: 7,
      // Which captured state is on screen (edit/capture.js names). A new state replaces the old one instantly, like the app.
      images: [{ at: 0, capture: "inbox" }, { at: 3.4, capture: "invoice-open" }],
      // Camera: glides to a captured target (capture.target) at a zoom; omit target for the whole screen. Zoom \u2264 1.8.
      camera: [{ at: 0 }, { at: 1.2, target: "inbox.list", zoom: 1.35 }, { at: 3.6, target: "invoice-open.total", zoom: 1.6 }],
      // Cursor: glides to a target, then clicks. Clicks land on the frame where the next state appears.
      cursor: [{ at: 0.6, target: "inbox.first" }, { at: 3.4, click: true }],
      overlays: null,
    },
    { id: "end", kind: "end", len: 5 },
  ],
  headlines: [
    ["inbox", 0.3, 3.2, "left", "Every invoice|in one inbox"],
    ["inbox", 3.6, 6.7, "left", "Approve|in one click"],
  ],
  // [shot, start, file]: media/narration/<file>.wav (wallet text to speech) with media/words/<file>.json.
  narration: [
    ["inbox", 0.3, "line-1"],
    ["inbox", 3.6, "line-2"],
  ],
  music: null,
});
