import { SHOTS, NARRATION, kept, place } from "../edit/timeline.js";
import { MEDIA, ROOT } from "./lib/config.mjs";

function words(file) {
  const data = JSON.parse(readFileSync(file, "utf8"));
  const list = Array.isArray(data) ? data : data.words ?? (data.segments ?? []).flatMap((s) => s.words ?? []);
  return list.filter((w) => (w.type ?? "word") === "word")
    .map((w) => ({ t: String(w.text ?? w.word ?? "").trim(), s: Number(w.start ?? w.start_time), e: Number(w.end ?? w.end_time) }))
    .filter((w) => w.t && Number.isFinite(w.s) && Number.isFinite(w.e));
}

